  "Changes employees ask HR to make to their profile. Everyone who answers HR Help tickets, and any full-access user, sees all of them.": "ఉద్యోగులు తమ ప్రొఫైల్‌లో చేయమని HRని కోరే మార్పులు. HR సహాయ టికెట్లకు సమాధానం ఇచ్చే వారందరూ, మరియు పూర్తి యాక్సెస్ ఉన్న ఏ వినియోగదారుడైనా వాటన్నింటినీ చూడగలరు.",
  "Counts show only what the server lets you see. Onboarding approvals are in Review & Onboarding, and bank-change requests are in the employee record; they are not part of this list.": "సర్వర్ మీకు చూపించేవి మాత్రమే సంఖ్యలలో కనిపిస్తాయి. ఆన్‌బోర్డింగ్ ఆమోదాలు \"సమీక్ష & ఆన్‌బోర్డింగ్\"లో ఉంటాయి, బ్యాంక్ మార్పు అభ్యర్థనలు ఉద్యోగి రికార్డులో ఉంటాయి; అవి ఈ జాబితాలో భాగం కావు.",
  "Cycle sign-off for your team or payroll scope. Open the tab to see what is due.": "మీ బృందం లేదా పేరోల్ పరిధికి చక్ర సంతకం. ఏమి గడువులో ఉందో చూడటానికి ట్యాబ్‌ను తెరవండి.",
  "Employees assigned to you; with no assigned HR, employees on your branch. A full-access user sees all.": "మీకు కేటాయించిన ఉద్యోగులు; కేటాయించిన HR లేకపోతే, మీ శాఖలోని ఉద్యోగులు. పూర్తి యాక్సెస్ ఉన్న వినియోగదారు అందరినీ చూస్తారు.",
