  "for every employee. Every web punch needs a live face match against an approved Face ID; until one exists, web clock-in/out is blocked unless you allow the fallback below.": "ప్రతి ఉద్యోగికి. ప్రతి వెబ్ పంచ్‌కు ఆమోదించిన Face IDతో ప్రత్యక్ష ఫేస్ సరిపోలిక అవసరం; ఒకటి ఉండే వరకు, మీరు కింది ప్రత్యామ్నాయాన్ని అనుమతిస్తే తప్ప వెబ్ క్లాక్-ఇన్/అవుట్ నిలిపివేయబడుతుంది.",
