  "How many days back an employee can request work from home. Not allowed (recommended): today or a later date only, because an approved request for a past day relabels that day after the fact and the home-location check cannot be met.": "ఉద్యోగి ఎన్ని రోజులు వెనక్కి ఇంటి నుండి పని అభ్యర్థించవచ్చు. అనుమతి లేదు (సిఫార్సు చేయబడింది): ఈ రోజు లేదా తర్వాతి తేదీ మాత్రమే, ఎందుకంటే గత రోజుకు ఆమోదించిన అభ్యర్థన ఆ రోజును తర్వాత మార్చివేస్తుంది మరియు ఇంటి ప్రదేశ తనిఖీ నెరవేరదు.",
