  "off": "ఆఫ్",
  "Off (recommended): a finished day of the half-day limit or fewer is a Half Day; a day above it but short of the full-day minimum stays Present and is shown as “hours not completed” with the minutes short. On: every day below the full-day minimum is a Half Day.": "ఆఫ్ (సిఫార్సు చేయబడింది): అర్ధ రోజు పరిమితి లేదా అంతకంటే తక్కువ గంటలతో ముగిసిన రోజు అర్ధ రోజు అవుతుంది; దాని కంటే ఎక్కువ కానీ పూర్తి రోజు కనీసం కంటే తక్కువ ఉన్న రోజు హాజరుగానే ఉంటుంది మరియు తక్కువ నిమిషాలతో “గంటలు పూర్తి కాలేదు” అని చూపబడుతుంది. ఆన్: పూర్తి రోజు కనీసం కంటే తక్కువ ఉన్న ప్రతి రోజు అర్ధ రోజు అవుతుంది.",
