  "Nominees are chosen from this list, and the parents' names on step 1 are filled from it. Add family before setting nominations.": "నామినీలను ఈ జాబితా నుండి ఎంచుకుంటారు, 1వ దశలో తల్లిదండ్రుల పేర్లు దీని నుండే నింపబడతాయి. నామినేషన్లు పెట్టే ముందు కుటుంబాన్ని జోడించండి.",
  "Not required of a private employer. Collect only where a government, PSU or aided establishment must report it, or a state incentive scheme requires it. Self-declared, and hidden from reporting managers.": "ప్రైవేట్ యజమానికి అవసరం లేదు. ప్రభుత్వ, PSU లేదా సహాయం పొందే సంస్థ నివేదించాల్సిన చోట, లేదా రాష్ట్ర ప్రోత్సాహక పథకానికి అవసరమైన చోట మాత్రమే సేకరించండి. స్వీయ ప్రకటన, రిపోర్టింగ్ మేనేజర్లకు కనిపించదు.",
