  "Required for EPF Form 2. Nominees are picked from the family list, so a name is only typed once. Each scheme should total 100%.": "EPF ఫారం 2కు అవసరం. నామినీలను కుటుంబ జాబితా నుండి ఎంచుకుంటారు, కాబట్టి పేరును ఒక్కసారే టైప్ చేయాలి. ప్రతి పథకం మొత్తం 100% ఉండాలి.",
