  "No lifecycle events on record yet.": "ఇంకా జీవితచక్ర సంఘటనలు నమోదు కాలేదు.",
  "Non-statutory fields erasable on request; statutory records cannot be deleted early": "చట్టబద్ధం కాని ఫీల్డ్‌లను అభ్యర్థనపై తొలగించవచ్చు; చట్టబద్ధ రికార్డులను ముందుగా తొలగించలేరు",
