  "This account has no employee record on file (no employee number assigned), so employment, pay, statutory, and history details below are unavailable. This is expected for an admin/system login that was never onboarded as an employee — sign in as an onboarded employee to see a full record.": "ఈ ఖాతాకు ఉద్యోగి రికార్డు లేదు (ఉద్యోగి నంబర్ కేటాయించలేదు), కాబట్టి క్రింద ఉన్న ఉద్యోగం, జీతం, చట్టబద్ధ మరియు చరిత్ర వివరాలు అందుబాటులో లేవు. ఉద్యోగిగా ఆన్‌బోర్డ్ కాని అడ్మిన్/సిస్టమ్ లాగిన్‌కు ఇది సహజమే — పూర్తి రికార్డు చూడడానికి ఆన్‌బోర్డ్ అయిన ఉద్యోగిగా సైన్ ఇన్ చేయండి.",
  "This employee submitted a bank detail change awaiting your review — their previous details remain active for payroll until you decide.": "ఈ ఉద్యోగి బ్యాంకు వివరాల మార్పును సమర్పించారు, అది మీ సమీక్ష కోసం వేచి ఉంది — మీరు నిర్ణయించే వరకు వారి మునుపటి వివరాలే పేరోల్‌కు చురుకుగా ఉంటాయి.",
  "UAN": "UAN",
  "Click to choose the filled .xlsx file": "నింపిన .xlsx ఫైల్‌ను ఎంచుకోవడానికి క్లిక్ చేయండి",
