  "Download errors (Excel)": "లోపాలను డౌన్‌లోడ్ చేయండి (Excel)",
  "Download template (.xlsx)": "టెంప్లేట్‌ను డౌన్‌లోడ్ చేయండి (.xlsx)",
  "Download the template and fill it in.": "టెంప్లేట్‌ను డౌన్‌లోడ్ చేసి నింపండి.",
  "Each new employee then gets an activation email.": "తర్వాత ప్రతి కొత్త ఉద్యోగికి యాక్టివేషన్ ఈమెయిల్ వస్తుంది.",
  "Every row must be valid to start.": "ప్రారంభించడానికి ప్రతి వరుస సరిగ్గా ఉండాలి.",
  "Everything is valid. Press Confirm to create these employees.": "అన్నీ సరిగ్గా ఉన్నాయి. ఈ ఉద్యోగులను సృష్టించడానికి నిర్ధారించండి నొక్కండి.",
  "Fix the rows below (or download the error file), then upload again. Nothing has been created.": "క్రింది వరుసలను సరిచేయండి (లేదా లోపాల ఫైల్‌ను డౌన్‌లోడ్ చేయండి), తర్వాత మళ్లీ అప్‌లోడ్ చేయండి. ఏదీ సృష్టించబడలేదు.",
  "Import another file": "మరొక ఫైల్‌ను ఇంపోర్ట్ చేయండి",
