  "Starting…": "ప్రారంభమవుతోంది…",
  "The employees are then created in the background, so you can close this window and come back: progress is saved.": "తర్వాత ఉద్యోగులు బ్యాక్‌గ్రౌండ్‌లో సృష్టించబడతారు, కాబట్టి ఈ విండోను మూసివేసి తిరిగి రావచ్చు: పురోగతి సేవ్ అవుతుంది.",
  "Upload it and review the preview — nothing is created yet.": "దాన్ని అప్‌లోడ్ చేసి ప్రివ్యూను సమీక్షించండి — ఇంకా ఏదీ సృష్టించబడదు.",
