  "Raised by": "అభ్యర్థించినవారు",
  "Recording a separation ends the current record and starts the exit process. It cannot be reversed — a returning employee needs a fresh Hire action.": "విడుదలను నమోదు చేస్తే ప్రస్తుత రికార్డు ముగిసి నిష్క్రమణ ప్రక్రియ ప్రారంభమవుతుంది. దీన్ని వెనక్కి తీసుకోలేరు — తిరిగి వచ్చే ఉద్యోగికి కొత్త నియామక చర్య అవసరం.",
  "Reversibility": "తిరిగి మార్చగలగడం",
