  "unchanged": "మారలేదు",
  "HR Business Partner → Payroll Admin.": "HR బిజినెస్ పార్ట్‌నర్ → పేరోల్ అడ్మిన్.",
  "HR, then Branch Admin (this employee is a manager, per the real separation approval chain).": "HR, తర్వాత బ్రాంచ్ అడ్మిన్ (ఈ ఉద్యోగి మేనేజర్, నిజమైన విడుదల ఆమోద శ్రేణి ప్రకారం).",
  "Not reversible. Undoing a separation requires a fresh Hire action and a new employee record — the original number is not reissued.": "వెనక్కి తీసుకోలేరు. విడుదలను రద్దు చేయడానికి కొత్త నియామక చర్య మరియు కొత్త ఉద్యోగి రికార్డు అవసరం — అసలు నంబర్ మళ్లీ ఇవ్వబడదు.",
  "Reporting manager (raises) → HR Business Partner, then Payroll Admin if a new CTC is included.": "రిపోర్టింగ్ మేనేజర్ (అభ్యర్థిస్తారు) → HR బిజినెస్ పార్ట్‌నర్, కొత్త CTC ఉంటే తర్వాత పేరోల్ అడ్మిన్.",
  "Reporting manager (raises) → HR Business Partner.": "రిపోర్టింగ్ మేనేజర్ (అభ్యర్థిస్తారు) → HR బిజినెస్ పార్ట్‌నర్.",
  "Reporting manager, then HR (the real separation approval chain for this employee).": "రిపోర్టింగ్ మేనేజర్, తర్వాత HR (ఈ ఉద్యోగికి నిజమైన విడుదల ఆమోద శ్రేణి).",
  "Requires employees.confirm — HR/Admin applies this directly, with the effective date and reason recorded in the audit trail.": "employees.confirm అవసరం — HR/అడ్మిన్ దీన్ని నేరుగా అమలు చేస్తారు, అమలు తేదీ మరియు కారణం ఆడిట్ ట్రైల్‌లో నమోదవుతాయి.",
  "Requires employees.edit — applied directly by whoever has that permission (typically the reporting manager or HR); no queued approval step exists for this action yet.": "employees.edit అవసరం — ఆ అనుమతి ఉన్నవారు (సాధారణంగా రిపోర్టింగ్ మేనేజర్ లేదా HR) నేరుగా అమలు చేస్తారు; ఈ చర్యకు ఇంకా క్యూలో ఆమోద దశ లేదు.",
  "Requires employees.edit — currently held by {name} or HR; no queued approval step exists for this action yet.": "employees.edit అవసరం — ప్రస్తుతం {name} లేదా HR వద్ద ఉంది; ఈ చర్యకు ఇంకా క్యూలో ఆమోద దశ లేదు.",
  "Requires employees.edit; no queued approval step exists for this action yet.": "employees.edit అవసరం; ఈ చర్యకు ఇంకా క్యూలో ఆమోద దశ లేదు.",
  "Requires payroll.edit — typically an HR Business Partner or Payroll Admin; no queued approval step exists for this action yet.": "payroll.edit అవసరం — సాధారణంగా HR బిజినెస్ పార్ట్‌నర్ లేదా పేరోల్ అడ్మిన్; ఈ చర్యకు ఇంకా క్యూలో ఆమోద దశ లేదు.",
  "Reversible going forward, but any payroll run already processed on this record must be corrected through arrears.": "ముందుకు వెళ్లేటప్పుడు తిరిగి మార్చవచ్చు, కానీ ఈ రికార్డుపై ఇప్పటికే ప్రాసెస్ అయిన పేరోల్ రన్‌ను బకాయిల ద్వారా సరిచేయాలి.",
  "Reversible. A correction action delimits this record and restores the previous position; the history keeps both.": "తిరిగి మార్చవచ్చు. సవరణ చర్య ఈ రికార్డును ముగించి మునుపటి స్థానాన్ని పునరుద్ధరిస్తుంది; చరిత్ర రెండింటినీ ఉంచుతుంది.",
  "Reversible. Record a further org assignment to move the employee back.": "తిరిగి మార్చవచ్చు. ఉద్యోగిని వెనక్కి మార్చడానికి మరో ఆర్గ్ కేటాయింపును నమోదు చేయండి.",
  "This is a one-way transition from probation to confirmed/active. Verify the employee and effective date before applying.": "ఇది ప్రొబేషన్ నుండి నిర్ధారిత/చురుకైన స్థితికి ఒకవైపు మార్పు. అమలు చేసే ముందు ఉద్యోగిని మరియు అమలు తేదీని ధృవీకరించండి.",
  "{action} sent for approval.": "{action} ఆమోదం కోసం పంపబడింది.",
