  "Face ID registration isn't required at the moment. It starts to apply if your organisation turns on": "ప్రస్తుతం Face ID నమోదు అవసరం లేదు. మీ సంస్థ ఆన్ చేస్తే ఇది వర్తించడం ప్రారంభమవుతుంది:",
