  "Select an asset type for every entry.": "ప్రతి నమోదుకు ఆస్తి రకాన్ని ఎంచుకోండి.",
  "Select an education type for every entry.": "ప్రతి నమోదుకు విద్య రకాన్ని ఎంచుకోండి.",
