  "Regime": "విధానం",
  "This locks {name}'s FY {year} declaration ({regime}, {deductions} deductions after limits) — they will no longer be able to change their regime or declared investments for this financial year.": "ఇది {name} FY {year} ప్రకటనను ({regime}, పరిమితుల తర్వాత {deductions} తగ్గింపులు) లాక్ చేస్తుంది — ఈ ఆర్థిక సంవత్సరానికి వారు ఇకపై తమ విధానాన్ని లేదా ప్రకటించిన పెట్టుబడులను మార్చలేరు.",
  "Income from a previous employer": "మునుపటి యజమాని నుండి ఆదాయం",
  "Joined this year? Enter what your previous employer paid you and the tax they deducted this financial year (from your Form 16 or last payslip). Leave blank if this is your first job this year.": "ఈ సంవత్సరం చేరారా? ఈ ఆర్థిక సంవత్సరంలో మీ మునుపటి యజమాని మీకు చెల్లించిన మొత్తం మరియు తగ్గించిన పన్నును (మీ ఫారం 16 లేదా చివరి పేస్లిప్ నుండి) నమోదు చేయండి. ఇది ఈ సంవత్సరం మీ మొదటి ఉద్యోగం అయితే ఖాళీగా వదిలేయండి.",
