  "Registering a face ID needs camera access. Allow it for this site in your browser's settings, then try again.": "ఫేస్ IDని నమోదు చేయడానికి కెమెరా యాక్సెస్ అవసరం. మీ బ్రౌజర్ సెట్టింగ్‌లలో ఈ సైట్‌కు దాన్ని అనుమతించి, మళ్లీ ప్రయత్నించండి.",
  "Registering face ID…": "ఫేస్ ID నమోదవుతోంది…",
