  "Failed to remove document.": "పత్రాన్ని తొలగించడం విఫలమైంది.",
  "Failed to upload document.": "పత్రాన్ని అప్‌లోడ్ చేయడం విఫలమైంది.",
  "Fill in the city or district of the current address (further down) first. Suggest uses it.": "ముందుగా ప్రస్తుత చిరునామాలోని (కింద ఉన్న) నగరం లేదా జిల్లాను పూరించండి. \"సూచించు\" దాన్ని ఉపయోగిస్తుంది.",
  "Generated from name": "పేరు నుండి రూపొందించబడింది",
