  "Save & exit": "సేవ్ చేసి నిష్క్రమించండి",
  "Saved, with a problem": "సేవ్ అయింది, కానీ సమస్యతో",
  "Scan & fill": "స్కాన్ చేసి పూరించండి",
  "The draft and everything entered so far will be deleted, and its reserved employee number is released. This cannot be undone. To keep it, use Save & exit instead.": "డ్రాఫ్ట్ మరియు ఇప్పటివరకు నమోదు చేసినవన్నీ తొలగించబడతాయి, రిజర్వ్ చేసిన ఉద్యోగి నంబర్ విడుదల అవుతుంది. దీన్ని వెనక్కి తీసుకోలేరు. ఉంచాలంటే బదులుగా \"సేవ్ చేసి నిష్క్రమించండి\" ఉపయోగించండి.",
  "The new hire": "కొత్తగా చేరినవారు",
  "The server did not keep: {fields}. Nothing was hired. Open that step, re-enter it, wait for \"Saved\", and press Hire again.": "సర్వర్ ఉంచలేదు: {fields}. ఎవరినీ నియమించలేదు. ఆ దశను తెరిచి, మళ్లీ నమోదు చేసి, \"సేవ్ అయింది\" వచ్చే వరకు వేచి ఉండి, మళ్లీ నియమించు నొక్కండి.",
  "Type the first and last name first. Suggest builds the display name from them.": "ముందుగా మొదటి మరియు చివరి పేరును టైప్ చేయండి. \"సూచించు\" వాటి నుండి ప్రదర్శన పేరును రూపొందిస్తుంది.",
  "You will need to upload it again before hiring.": "నియమించే ముందు మీరు దీన్ని మళ్లీ అప్‌లోడ్ చేయాలి.",
  "Your entries could not be saved, so nothing was hired. {message}": "మీ నమోదులు సేవ్ కాలేదు, కాబట్టి ఎవరినీ నియమించలేదు. {message}",
