  "The new hire cannot register it themselves.": "కొత్తగా చేరినవారు దీన్ని స్వయంగా నమోదు చేయలేరు.",
  "The new hire registers their Face ID from their Profile page, and HR approves it on": "కొత్తగా చేరినవారు తమ ప్రొఫైల్ పేజీ నుండి ఫేస్ IDని నమోదు చేస్తారు, HR దాన్ని ఇక్కడ ఆమోదిస్తుంది:",
  "The new hire registers their own Face ID from their Profile page; it is active immediately.": "కొత్తగా చేరినవారు తమ ప్రొఫైల్ పేజీ నుండి తమ ఫేస్ IDని నమోదు చేస్తారు; అది వెంటనే చురుకుగా ఉంటుంది.",
  "the record can still be created in Onboarding status.": "రికార్డును ఇంకా ఆన్‌బోర్డింగ్ స్థితిలో సృష్టించవచ్చు.",
  "The record is created in Onboarding status. Optional details (father/mother's name, non-required documents) can still be finished afterward.": "రికార్డు ఆన్‌బోర్డింగ్ స్థితిలో సృష్టించబడుతుంది. ఐచ్ఛిక వివరాలను (తండ్రి/తల్లి పేరు, అవసరం లేని పత్రాలు) తర్వాత కూడా పూర్తి చేయవచ్చు.",
  "Until it is done they cannot clock in on the web.": "అది పూర్తయ్యే వరకు వారు వెబ్‌లో క్లాక్ ఇన్ చేయలేరు.",
  "Until then they can still clock in from the office; those punches are flagged for HR.": "అప్పటి వరకు వారు ఆఫీసు నుండి క్లాక్ ఇన్ చేయవచ్చు; ఆ పంచ్‌లు HR కోసం గుర్తించబడతాయి.",
