  "FOUND IN DOCUMENT": "పత్రంలో కనిపించినవి",
  "Scanning…": "స్కాన్ అవుతోంది…",
  "Upload a text-based PDF (an offer letter, ID or resume exported as PDF). This reads the actual text in the document and matches recognizable fields — it does not guess anything not on the page.": "టెక్స్ట్ ఆధారిత PDFని అప్‌లోడ్ చేయండి (PDFగా ఎగుమతి చేసిన ఆఫర్ లెటర్, ID లేదా రెజ్యూమె). ఇది పత్రంలోని అసలు టెక్స్ట్‌ను చదివి గుర్తించదగిన ఫీల్డ్‌లను సరిపోలుస్తుంది — పేజీలో లేనిదాన్ని ఊహించదు.",
