  "Permanently delete \"{name}\"? This can't be undone, and only works if none of its positions have ever been held by anyone — if any have, this will be rejected; deactivate the unit instead.": "\"{name}\"ని శాశ్వతంగా తొలగించాలా? దీన్ని వెనక్కి తీసుకోలేరు, మరియు దాని స్థానాలలో ఏవీ ఎప్పుడూ ఎవరికీ ఉండకపోతేనే ఇది పనిచేస్తుంది — ఉంటే ఇది తిరస్కరించబడుతుంది; బదులుగా విభాగాన్ని నిష్క్రియం చేయండి.",
