  ", not a person. You mark one position in each unit as": ", వ్యక్తి కాదు. ప్రతి యూనిట్‌లో ఒక పొజిషన్‌ను ఇలా గుర్తిస్తారు:",
  "; whoever holds it is the head. The seat can stay": "; దానిని కలిగి ఉన్నవారే హెడ్. సీటు ఇలా ఉండవచ్చు:",
  ". Access belongs to that seat—not the reporting chain; employees sharing a seat share its permissions. Use separate positions when employees need different access.": ". యాక్సెస్ ఆ సీటుకు చెందుతుంది—రిపోర్టింగ్ చైన్‌కు కాదు; ఒకే సీటును పంచుకునే ఉద్యోగులు దాని అనుమతులను పంచుకుంటారు. ఉద్యోగులకు వేర్వేరు యాక్సెస్ అవసరమైతే వేర్వేరు పొజిషన్లను ఉపయోగించండి.",
