  "Team manager": "టీమ్ మేనేజర్",
  "These permissions belong to this position. The current holder receives them; a future holder receives the same access. Permissions do not automatically pass between a manager and their reports. Give each position its own access below.": "ఈ అనుమతులు ఈ పొజిషన్‌కు చెందినవి. ప్రస్తుత హోల్డర్ వీటిని పొందుతారు; భవిష్యత్ హోల్డర్ కూడా అదే యాక్సెస్ పొందుతారు. అనుమతులు మేనేజర్ నుండి వారి రిపోర్టీలకు ఆటోమేటిక్‌గా బదిలీ కావు. ప్రతి పొజిషన్‌కు దాని స్వంత యాక్సెస్‌ను క్రింద ఇవ్వండి.",
  "Turning on Team manager also checked the usual manager permissions below (View employees, Approve leave, View attendance) so this position isn't left with 0 permissions. Uncheck any you don't want before saving.": "టీమ్ మేనేజర్‌ను ఆన్ చేయడంతో ఈ పొజిషన్‌కు 0 అనుమతులు ఉండకుండా క్రింద ఉన్న సాధారణ మేనేజర్ అనుమతులు (ఉద్యోగులను చూడండి, సెలవును ఆమోదించండి, హాజరు చూడండి) కూడా ఎంచుకోబడ్డాయి. సేవ్ చేసే ముందు మీకు వద్దనుకున్నవాటిని ఎంపిక తీసివేయండి.",
