  "HR sign-off is the final step before payroll can be processed.": "పేరోల్ ప్రాసెస్ చేయడానికి ముందు HR ధృవీకరణ చివరి దశ.",
  "HR verifies and signs off — unlocks payroll processing": "HR పరిశీలించి ధృవీకరిస్తుంది — పేరోల్ ప్రాసెసింగ్‌ను అన్‌లాక్ చేస్తుంది",
  "L1 + L2 required": "L1 + L2 అవసరం",
