  "No managers with team management rights are configured — HR can approve directly.": "బృంద నిర్వహణ హక్కులు ఉన్న మేనేజర్లు ఎవరూ కాన్ఫిగర్ చేయబడలేదు — HR నేరుగా ఆమోదించవచ్చు.",
