  "Refresh status": "స్థితిని రిఫ్రెష్ చేయండి",
  "to sign off.": "ధృవీకరించడానికి.",
  "Waiting for all managers (L1) to approve first": "ముందుగా మేనేజర్లందరూ (L1) ఆమోదించే వరకు వేచి ఉంది",
  "Waiting for HR to sign off from": "HR ధృవీకరణ కోసం వేచి ఉంది, ఇక్కడ నుండి:",
  "Waiting for HR/Admin to complete the L1 step directly — no managers are configured for this cycle.": "HR/అడ్మిన్ L1 దశను నేరుగా పూర్తి చేయడం కోసం వేచి ఉంది — ఈ సైకిల్‌కు మేనేజర్లు ఎవరూ కాన్ఫిగర్ చేయబడలేదు.",
  "Waiting for other managers to approve. Refresh to check latest status.": "ఇతర మేనేజర్లు ఆమోదించే వరకు వేచి ఉంది. తాజా స్థితిని చూడడానికి రిఫ్రెష్ చేయండి.",
  "Your sign-off is required — approve it from": "మీ ధృవీకరణ అవసరం — దీని నుండి ఆమోదించండి:",
  "{amount} total": "మొత్తం {amount}",
  "All salaries marked as paid. Payroll run for this cycle is complete.": "అన్ని జీతాలు చెల్లించినట్లు గుర్తించబడ్డాయి. ఈ సైకిల్ పేరోల్ రన్ పూర్తయింది.",
  "Checking salary transfer readiness…": "జీతం బదిలీ సంసిద్ధతను తనిఖీ చేస్తోంది…",
  "Confirm and Lock": "నిర్ధారించి లాక్ చేయండి",
  "Confirm Salary Transfer": "జీతం బదిలీని నిర్ధారించండి",
  "Confirm salary transfer?": "జీతం బదిలీని నిర్ధారించాలా?",
  "Download NEFT CSV": "NEFT CSV డౌన్‌లోడ్ చేయండి",
  "Employees have acknowledged their payslips. Confirm the salary transfer to lock bank details and generate the NEFT CSV.": "ఉద్యోగులు తమ పేస్లిప్‌లను అంగీకరించారు. బ్యాంక్ వివరాలను లాక్ చేసి NEFT CSV తయారు చేయడానికి జీతం బదిలీని నిర్ధారించండి.",
  "Failed to confirm the salary transfer.": "జీతం బదిలీని నిర్ధారించడం విఫలమైంది.",
  "Failed to download the bank transfer file.": "బ్యాంక్ బదిలీ ఫైల్‌ను డౌన్‌లోడ్ చేయడం విఫలమైంది.",
  "Failed to mark as paid.": "చెల్లించినట్లు గుర్తించడం విఫలమైంది.",
