  "Net Salary": "నికర జీతం",
  "Paid": "చెల్లించబడింది",
  "Preparing CSV…": "CSV సిద్ధం చేస్తోంది…",
  "Salary transfer locked for {count} employee(s). Download the NEFT CSV and submit it to your bank before marking payroll paid.": "{count} మంది ఉద్యోగులకు జీతం బదిలీ లాక్ చేయబడింది. పేరోల్‌ను చెల్లించినట్లు గుర్తించే ముందు NEFT CSV డౌన్‌లోడ్ చేసి మీ బ్యాంక్‌కు సమర్పించండి.",
  "Salary transfer readiness is unavailable.": "జీతం బదిలీ సంసిద్ధత అందుబాటులో లేదు.",
  "This locks the current bank details and net pay for all {count} employee(s) into a transfer batch. Download the NEFT CSV after confirmation and submit it through your bank before marking payroll paid.": "ఇది మొత్తం {count} మంది ఉద్యోగుల ప్రస్తుత బ్యాంక్ వివరాలు మరియు నికర జీతాన్ని ఒక బదిలీ బ్యాచ్‌గా లాక్ చేస్తుంది. నిర్ధారణ తర్వాత NEFT CSV డౌన్‌లోడ్ చేసి, పేరోల్‌ను చెల్లించినట్లు గుర్తించే ముందు మీ బ్యాంక్ ద్వారా సమర్పించండి.",
  "This marks all {count} payslip (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "ఇది మొత్తం {count} పేస్లిప్‌ను (మొత్తం {amount}) చెల్లించినట్లు గుర్తించి ఈ పేరోల్ రన్‌ను ముగిస్తుంది. ఇది స్వయంగా డబ్బును బదిలీ చేయదు — బదిలీ ఇప్పటికే జరిగిందని నమోదు చేస్తుంది. దీనిని రద్దు చేయలేరు.",
  "This marks all {count} payslips (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "ఇది మొత్తం {count} పేస్లిప్‌లను (మొత్తం {amount}) చెల్లించినట్లు గుర్తించి ఈ పేరోల్ రన్‌ను ముగిస్తుంది. ఇది స్వయంగా డబ్బును బదిలీ చేయదు — బదిలీ ఇప్పటికే జరిగిందని నమోదు చేస్తుంది. దీనిని రద్దు చేయలేరు.",
