  "Set up their salary in Employees → Salary tab, then reprocess to include them.": "ఉద్యోగులు → జీతం ట్యాబ్‌లో వారి జీతాన్ని సెటప్ చేసి, ఆపై వారిని చేర్చడానికి మళ్లీ ప్రాసెస్ చేయండి.",
  "Spl. Allow.": "ప్రత్యేక భత్యం",
  "Statutory Deductions": "చట్టబద్ధ తగ్గింపులు",
  "This recalculates salaries for all {count} employee in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "ఇది ఈ సైకిల్‌లోని మొత్తం {count} ఉద్యోగి జీతాలను మొదటి నుండి మళ్లీ లెక్కించి, ప్రస్తుత గణాంకాలను — ఈ పేస్లిప్‌లపై ఇప్పటికే చేసిన మాన్యువల్ బోనస్ లేదా రీయింబర్స్‌మెంట్ సర్దుబాట్లతో సహా — మార్చివేస్తుంది. దీనిని రద్దు చేయలేరు.",
  "This recalculates salaries for all {count} employees in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "ఇది ఈ సైకిల్‌లోని మొత్తం {count} మంది ఉద్యోగుల జీతాలను మొదటి నుండి మళ్లీ లెక్కించి, ప్రస్తుత గణాంకాలను — ఈ పేస్లిప్‌లపై ఇప్పటికే చేసిన మాన్యువల్ బోనస్ లేదా రీయింబర్స్‌మెంట్ సర్దుబాట్లతో సహా — మార్చివేస్తుంది. దీనిని రద్దు చేయలేరు.",
  "This will calculate salaries for all eligible employees using their CTC, salary structure, and statutory rules for each branch.": "ఇది అర్హులైన ఉద్యోగులందరికీ వారి CTC, జీతం నిర్మాణం మరియు ప్రతి బ్రాంచ్ చట్టబద్ధ నియమాల ఆధారంగా జీతాలను లెక్కిస్తుంది.",
