  "Notice Period Recovery": "నోటీసు కాలం రికవరీ",
  "Notice period shortfall:": "నోటీసు కాలం కొరత:",
  "Other Adjustment (+/−)": "ఇతర సర్దుబాటు (+/−)",
  "Other Adjustment Note": "ఇతర సర్దుబాటు గమనిక",
  "Other Adjustment: {amount}": "ఇతర సర్దుబాటు: {amount}",
  "Pro-rata Salary": "దామాషా జీతం",
  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "దామాషా జీతం, సెలవు నగదీకరణ మరియు నోటీసు కాలం కొరత ఆటోమేటిక్‌గా లెక్కించబడతాయి (CTC ÷ 30, ఆర్జిత సెలవు నిల్వ) — ఇది సమీక్షించడానికి ప్రారంభ అంచనా మాత్రమే, తుది మొత్తం కాదు. గ్రాట్యుటీ, బోనస్, రీయింబర్స్‌మెంట్లు, అడ్వాన్స్‌లు మరియు TDS ఎల్లప్పుడూ చేతితో నమోదు చేయాలి.",
  "Settlement finalized.": "సెటిల్‌మెంట్ ఖరారు చేయబడింది.",
  "Settlement updated.": "సెటిల్‌మెంట్ నవీకరించబడింది.",
  "This is a recovery — the employee owes the company (net payable may be negative)": "ఇది రికవరీ — ఉద్యోగి కంపెనీకి చెల్లించాలి (నికర చెల్లింపు రుణాత్మకంగా ఉండవచ్చు)",
  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ఇది పూర్తి & తుది సెటిల్‌మెంట్‌ను నికర చెల్లింపు {amount} వద్ద లాక్ చేస్తుంది. ఖరారు చేసిన తర్వాత ఈ సెటిల్‌మెంట్‌లోని ఏ ఫీల్డ్‌ను — గ్రాట్యుటీ, బోనస్, రీయింబర్స్‌మెంట్లు, అడ్వాన్స్‌లు, TDS లేదా సర్దుబాట్లు — మళ్లీ సవరించలేరు. దీనిని రద్దు చేయలేరు.",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ఇది పూర్తి & తుది సెటిల్‌మెంట్‌ను ఉద్యోగి నుండి వసూలు చేయాల్సిన నికర మొత్తం {amount} వద్ద లాక్ చేస్తుంది. ఖరారు చేసిన తర్వాత ఈ సెటిల్‌మెంట్‌లోని ఏ ఫీల్డ్‌ను — గ్రాట్యుటీ, బోనస్, రీయింబర్స్‌మెంట్లు, అడ్వాన్స్‌లు, TDS లేదా సర్దుబాట్లు — మళ్లీ సవరించలేరు. దీనిని రద్దు చేయలేరు.",
