  "extra access for just one specific employee, on top of their position.": "ఒక నిర్దిష్ట ఉద్యోగికి మాత్రమే, వారి పొజిషన్‌కు అదనంగా ఇచ్చే యాక్సెస్.",
  "give the same permissions to many positions at once, e.g. every manager.": "ఒకేసారి అనేక పొజిషన్లకు అవే అనుమతులు ఇవ్వండి, ఉదా. ప్రతి మేనేజర్‌కు.",
