  "what every employee can do, no matter their position.": "పొజిషన్‌తో సంబంధం లేకుండా ప్రతి ఉద్యోగి చేయగలిగినవి.",
  "What every employee can do, whatever their position. Changes take effect the next time each person signs in.": "పొజిషన్ ఏదైనా సరే ప్రతి ఉద్యోగి చేయగలిగినవి. ప్రతి వ్యక్తి తదుపరిసారి సైన్ ఇన్ చేసినప్పుడు మార్పులు అమలులోకి వస్తాయి.",
