  "Category cannot be changed after creation.": "సృష్టించిన తర్వాత వర్గాన్ని మార్చలేరు.",
  "Create “{name}”": "“{name}” సృష్టించండి",
  "Create Template": "టెంప్లేట్ సృష్టించండి",
