  "Deactivate Salary Structure?": "జీతం నిర్మాణాన్ని డియాక్టివేట్ చేయాలా?",
  "Default: next payroll cycle start ({date}).": "డిఫాల్ట్: తదుపరి పేరోల్ సైకిల్ ప్రారంభం ({date}).",
  "Defaults to the next payroll cycle; issued payslips are not recalculated.": "డిఫాల్ట్‌గా తదుపరి పేరోల్ సైకిల్; జారీ చేసిన పేస్లిప్‌లు మళ్లీ లెక్కించబడవు.",
