  "A nominee is picked from the family list, and there is nobody in it yet. Add a family member with a name above, then add the nominee.": "నామినీని కుటుంబ జాబితా నుండి ఎంచుకుంటారు, అందులో ఇంకా ఎవరూ లేరు. పైన పేరుతో కుటుంబ సభ్యుడిని జోడించి, ఆపై నామినీని జోడించండి.",
