  "Add the people who depend on the employee or who may be nominated below. A person is added once and can be picked as a nominee.": "ఉద్యోగిపై ఆధారపడేవారిని లేదా నామినేట్ చేయదగినవారిని క్రింద జోడించండి. ఒక వ్యక్తిని ఒకసారి జోడిస్తే నామినీగా ఎంచుకోవచ్చు.",
  "Another {relationship} is already listed.": "మరొక {relationship} ఇప్పటికే జాబితాలో ఉన్నారు.",
  "Each scheme's shares should add up to 100% across its nominees. Pick nominees from the family list above.": "ప్రతి పథకం వాటాలు దాని నామినీల మధ్య మొత్తం 100% అయ్యేలా ఉండాలి. పై కుటుంబ జాబితా నుండి నామినీలను ఎంచుకోండి.",
