  "Drag and drop a file onto any row below, or click Upload. Accepted: PDF, JPG, PNG · Max 5 MB each.": "క్రింది ఏదైనా వరుసపై ఫైల్‌ను లాగి వదలండి, లేదా అప్‌లోడ్ క్లిక్ చేయండి. అంగీకరించేవి: PDF, JPG, PNG · ఒక్కొక్కటి గరిష్టంగా 5 MB.",
