  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, and it takes effect immediately.": "వెబ్ క్లాక్-ఇన్/అవుట్ కోసం మీ సంస్థకు నమోదైన ఫేస్ ID అవసరం. ఇక్కడ ఒకసారి నమోదు చేయండి — ఇది నిజంగా మీరేనని నిర్ధారించడానికి త్వరిత లైవ్‌నెస్ తనిఖీ చేస్తాము, ఇది వెంటనే అమలులోకి వస్తుంది.",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, then send it to HR for approval.": "వెబ్ క్లాక్-ఇన్/అవుట్ కోసం మీ సంస్థకు నమోదైన ఫేస్ ID అవసరం. ఇక్కడ ఒకసారి నమోదు చేయండి — ఇది నిజంగా మీరేనని నిర్ధారించడానికి త్వరిత లైవ్‌నెస్ తనిఖీ చేసి, ఆపై ఆమోదం కోసం HRకు పంపుతాము.",
