  "Calibrated, ready to publish": "సమన్వయం చేయబడింది, ప్రచురణకు సిద్ధం",
  "Choose the state and city. The Company Code is made from the city for you.": "రాష్ట్రం మరియు నగరాన్ని ఎంచుకోండి. కంపెనీ కోడ్ నగరం నుండి మీ కోసం తయారవుతుంది.",
