  "Non-statutory fields can be erased on request. Statutory records cannot be deleted early.": "చట్టబద్ధం కాని ఫీల్డ్‌లను అభ్యర్థిస్తే తొలగించవచ్చు. చట్టబద్ధ రికార్డులను ముందుగా తొలగించలేరు.",
  "Non-statutory profile fields": "చట్టబద్ధం కాని ప్రొఫైల్ ఫీల్డ్‌లు",
  "On exit": "నిష్క్రమణ సమయంలో",
  "Onboarding Reviews": "ఆన్‌బోర్డింగ్ సమీక్షలు",
  "Passwords must be long enough, not a common password, not only numbers, and not too similar to your name or email.": "పాస్‌వర్డ్‌లు తగినంత పొడవుగా ఉండాలి, సాధారణ పాస్‌వర్డ్ కాకూడదు, కేవలం సంఖ్యలు కాకూడదు మరియు మీ పేరు లేదా ఈమెయిల్‌కు మరీ దగ్గరగా ఉండకూడదు.",
  "People with the right permission can review these in the Audit Log.": "సరైన అనుమతి ఉన్నవారు వీటిని ఆడిట్ లాగ్‌లో సమీక్షించవచ్చు.",
  "Privacy & retention": "గోప్యత & నిలుపుదల",
