  "Sign out on a shared computer. Signing out ends the session.": "షేర్ చేసిన కంప్యూటర్‌లో సైన్ అవుట్ చేయండి. సైన్ అవుట్ చేస్తే సెషన్ ముగుస్తుంది.",
  "Signing in": "సైన్ ఇన్ చేయడం",
  "Subject / Actor": "విషయం / చేసినవారు",
  "System administrators": "సిస్టమ్ అడ్మినిస్ట్రేటర్లు",
  "The link in an onboarding invitation works once, for 72 hours. If it expires, HR can send a new one, and the old link then stops working.": "ఆన్‌బోర్డింగ్ ఆహ్వానంలోని లింక్ 72 గంటల పాటు ఒక్కసారి మాత్రమే పనిచేస్తుంది. గడువు ముగిస్తే HR కొత్తది పంపవచ్చు, అప్పుడు పాత లింక్ పనిచేయదు.",
  "The rows and any errors are deleted.": "వరుసలు మరియు లోపాలు తొలగించబడతాయి.",
  "Their own information and their own requests.": "వారి సొంత సమాచారం మరియు వారి సొంత అభ్యర్థనలు.",
  "Their own team, not everyone.": "వారి సొంత బృందం, అందరూ కాదు.",
  "This page describes how the system works. It is not a certification or a guarantee. To report a concern, contact HR.": "ఈ పేజీ సిస్టమ్ ఎలా పనిచేస్తుందో వివరిస్తుంది. ఇది ధృవీకరణ లేదా హామీ కాదు. ఆందోళన తెలియజేయడానికి HRని సంప్రదించండి.",
  "This page describes how the system works. Your company's own policy and the law apply. For the full policy, ask HR.": "ఈ పేజీ సిస్టమ్ ఎలా పనిచేస్తుందో వివరిస్తుంది. మీ కంపెనీ సొంత విధానం మరియు చట్టం వర్తిస్తాయి. పూర్తి విధానం కోసం HRని అడగండి.",
  "To see, correct or ask to erase your information, raise an HR help request from the HR help tab on your workspace.": "మీ సమాచారాన్ని చూడటానికి, సరిచేయడానికి లేదా తొలగించమని అడగడానికి, మీ వర్క్‌స్పేస్‌లోని HR సహాయం ట్యాబ్ నుండి HR సహాయ అభ్యర్థన పెట్టండి.",
  "Until erasure is requested": "తొలగింపు అభ్యర్థించే వరకు",
  "Until the person leaves": "వ్యక్తి వెళ్లిపోయే వరకు",
  "What AIRA keeps about you, for how long, and who can see it.": "AIRA మీ గురించి ఏమి ఉంచుతుంది, ఎంతకాలం, మరియు ఎవరు చూడగలరు.",
  "What happens": "ఏమి జరుగుతుంది",
  "What is kept, and why": "ఏమి ఉంచబడుతుంది, ఎందుకు",
  "What they can see": "వారు ఏమి చూడగలరు",
  "When someone leaves, their stored Face ID registration is deleted. A record that a check happened is kept for audit, without the biometric data.": "ఎవరైనా వెళ్లిపోయినప్పుడు, వారి నిల్వ ఉన్న ఫేస్ ID నమోదు తొలగించబడుతుంది. తనిఖీ జరిగినట్లు రికార్డు బయోమెట్రిక్ డేటా లేకుండా ఆడిట్ కోసం ఉంచబడుతుంది.",
  "Where Face ID is set up, it is checked when you punch in or out.": "ఫేస్ ID సెట్ చేసిన చోట, మీరు పంచ్ ఇన్ లేదా అవుట్ చేసినప్పుడు అది తనిఖీ చేయబడుతుంది.",
  "While kept for compliance": "నియమ పాలన కోసం ఉంచబడినంత కాలం",
  "Who can do what": "ఎవరు ఏమి చేయగలరు",
  "Who can see it": "దీన్ని ఎవరు చూడగలరు",
  "Who sees what": "ఎవరు ఏమి చూస్తారు",
  "You cannot approve your own leave or expense requests.": "మీ సొంత సెలవు లేదా ఖర్చు అభ్యర్థనలను మీరు ఆమోదించలేరు.",
  "You stay signed in for up to 7 days. The short-lived part of your sign-in lasts 15 minutes and is renewed automatically while you are signed in.": "మీరు గరిష్టంగా 7 రోజుల వరకు సైన్ ఇన్‌లో ఉంటారు. మీ సైన్ ఇన్‌లోని స్వల్పకాలిక భాగం 15 నిమిషాలు ఉంటుంది, మరియు మీరు సైన్ ఇన్‌లో ఉన్నంత కాలం ఆటోమేటిక్‌గా పునరుద్ధరించబడుతుంది.",
