  "Location access is required for office punch in/out. Please allow location in your browser settings.": "ఆఫీస్ పంచ్ ఇన్/అవుట్ కోసం లొకేషన్ యాక్సెస్ అవసరం. దయచేసి మీ బ్రౌజర్ సెట్టింగ్‌లలో లొకేషన్‌ను అనుమతించండి.",
  "Location access is required for work-from-home punch in/out. Please allow location in your browser settings.": "ఇంటి నుండి పని పంచ్ ఇన్/అవుట్ కోసం లొకేషన్ యాక్సెస్ అవసరం. దయచేసి మీ బ్రౌజర్ సెట్టింగ్‌లలో లొకేషన్‌ను అనుమతించండి.",
  "Please register your Face ID first (Profile > Register My Face), then come back to punch in.": "దయచేసి ముందుగా మీ ఫేస్ ID నమోదు చేయండి (ప్రొఫైల్ > నా ముఖాన్ని నమోదు చేయండి), తర్వాత పంచ్ ఇన్ చేయడానికి తిరిగి రండి.",
  "Punch failed. Please try again.": "పంచ్ విఫలమైంది. దయచేసి మళ్లీ ప్రయత్నించండి.",
  "Punched in successfully.": "పంచ్ ఇన్ విజయవంతమైంది.",
  "Punched out successfully.": "పంచ్ అవుట్ విజయవంతమైంది.",
  "Too many failed face verification attempts. Please wait {time} before trying again.": "ముఖ ధృవీకరణ ప్రయత్నాలు చాలాసార్లు విఫలమయ్యాయి. మళ్లీ ప్రయత్నించే ముందు దయచేసి {time} వేచి ఉండండి.",
  "Unable to determine your location. Please check your device's location settings and try again.": "మీ లొకేషన్‌ను గుర్తించలేకపోయాము. దయచేసి మీ పరికరం లొకేషన్ సెట్టింగ్‌లను తనిఖీ చేసి మళ్లీ ప్రయత్నించండి.",
  "You are outside the allowed location for this branch.": "మీరు ఈ శాఖకు అనుమతించిన ప్రదేశం బయట ఉన్నారు.",
  "Your browser does not support location access.": "మీ బ్రౌజర్ లొకేషన్ యాక్సెస్‌కు మద్దతు ఇవ్వదు.",
  "Choose the filled template first.": "ముందుగా పూరించిన టెంప్లేట్‌ను ఎంచుకోండి.",
