  "The connection was lost, so the outcome is unknown. Press Confirm again: this import cannot be applied twice.": "కనెక్షన్ తెగిపోయింది, కాబట్టి ఫలితం తెలియదు. మళ్లీ \"నిర్ధారించండి\" నొక్కండి: ఈ దిగుమతి రెండుసార్లు వర్తించదు.",
